/* Binary format of the nx UI assets (fonts, icons, strings, palettes). The tables are generated by
 * tools/gen_nx_assets.py into src/nx/nx_assets.c and read by nx_font.c; tools/nxassets/glyphenc.py
 * writes exactly these layouts.
 *
 * Glyph bitmaps are alpha masks, row-major, no row padding, one of two encodings per glyph
 * (the tool keeps the smaller one):
 *   raw  bpp bits per pixel (font->bpp: 2 or 4), MSB first; 2 bpp value v means alpha 5*v.
 *   RLE  4-bit codes, high nibble first:  0,n = n+1 transparent pixels;  F,n = n+1 opaque pixels;
 *        1..E = one pixel with that alpha. Runs continue across rows; the stream ends after w*h
 *        pixels (a final pad nibble is ignored).
 * Decoded alpha is always 0..15 (15 = opaque). */
#pragma once

#include <stdint.h>

#define NX_GLYPH_RLE      0x8000u   /* nx_glyph_t.off: bitmap is RLE-coded */
#define NX_GLYPH_OFF_MASK 0x7FFFu   /* nx_glyph_t.off: byte offset into nx_font_t.data */

#define NX_ALPHA_MAX 15u

/* String tables: bytes 0x20..0x7E are ASCII, 0x80.. are the extra characters of the text fonts
 * (NX_CH_* in nx_assets.h); bytes 1..NX_STR_ARGS are argument slots for nx_str_format. */
#define NX_STR_ARGS 3u

typedef struct {
    uint16_t off;      /* NX_GLYPH_RLE | offset of the bitmap in the font's data */
    uint8_t w, h;      /* bitmap size; 0 x 0 = nothing to draw (space) */
    int8_t x_off;      /* bitmap left edge relative to the pen position */
    uint8_t y_off;     /* bitmap top edge relative to the line top */
    uint8_t advance;   /* pen advance in pixels */
    uint8_t reserved;  /* 0 */
} nx_glyph_t;

_Static_assert(sizeof(nx_glyph_t) == 8, "nx_glyph_t is an 8-byte record");

/* A font; an icon set is a font whose codes are icon indices 0..n-1 (dense), with
 * height = baseline = advance = the icon box size. */
typedef struct {
    uint8_t height;     /* line height in pixels */
    uint8_t baseline;   /* baseline position from the line top */
    uint8_t bpp;        /* depth of raw glyphs: 2 or 4 */
    uint8_t first;      /* dense code range first..last (glyphs[0..last-first]); first > last: none */
    uint8_t last;
    uint8_t n_extra;    /* further codes, sorted ascending, glyphs follow the dense ones */
    uint8_t reserved[2];
    const uint8_t *extra;
    const nx_glyph_t *glyphs;
    const uint8_t *data;
} nx_font_t;
